#include <stdio.h>

int main() {
    float base, height, area;

    // Input from user
    printf("Enter the base of the triangle: ");
    scanf("%f", &base);

    printf("Enter the height of the triangle: ");
    scanf("%f", &height);

    // Calculate area
    area = 0.5 * base * height;

    printf("\nArea of the triangle = %.2f square units\n", area);

    return 0;
}
